#!/usr/bin/env python3
"""Regenerate zipdata_gen.go from the REAL Python unicodedata and cp437 codec.

Run as:  python3 -I gen_tables.py > ../../zipdata_gen.go   (then gofmt -w)

Emits the tables the Go ports need so that a ZIP entry name is judged exactly as the legacy
zip_metadata.py / zip_stored.py judged it:
  zipCP437       bytes 0x80-0xff decoded with the cp437 codec (names without general-purpose flag 11)
  zipCanonDecomp one-level canonical decompositions (unicodedata.decomposition without a <tag>)
  zipCCC         canonical combining classes, as ranges
  zipCompose     primary composites: a two-rune decomposition that NFC maps back to itself
Hangul syllables are algorithmic and not listed.
"""
import sys
import unicodedata

HANGUL = range(0xAC00, 0xD7A4)


def main() -> None:
    out = ["// Code generated by testdata/zip/gen_tables.py from Python unicodedata %s; DO NOT EDIT." % unicodedata.unidata_version,
           "",
           "package formats",
           "",
           'const zipUnicodeVersion = "%s"' % unicodedata.unidata_version,
           ""]
    out.append("// zipCP437 is bytes 0x80-0xff decoded with the cp437 codec.")
    out.append("var zipCP437 = [128]rune{")
    row = []
    for b in range(0x80, 0x100):
        row.append("0x%04x" % ord(bytes([b]).decode("cp437")))
        if len(row) == 8:
            out.append("\t" + ", ".join(row) + ",")
            row = []
    out.append("}")
    out.append("")
    decomp, compose = [], []
    for cp in range(0x110000):
        if cp in HANGUL or 0xD800 <= cp <= 0xDFFF:
            continue
        d = unicodedata.decomposition(chr(cp))
        if not d or d.startswith("<"):
            continue
        parts = [int(x, 16) for x in d.split()]
        decomp.append((cp, parts[0], parts[1] if len(parts) > 1 else 0))
        if len(parts) == 2 and unicodedata.normalize("NFC", chr(cp)) == chr(cp):
            compose.append((parts[0], parts[1], cp))
    compose.sort()
    out.append("// zipCanonDecomp maps a rune to its one-level canonical decomposition (B is 0 for a singleton).")
    out.append("var zipCanonDecomp = []zipDecomp{")
    for i in range(0, len(decomp), 4):
        out.append("\t" + " ".join("{0x%x, 0x%x, 0x%x}," % t for t in decomp[i:i + 4]))
    out.append("}")
    out.append("")
    out.append("// zipCompose maps a starter and a following rune to their primary composite.")
    out.append("var zipCompose = []zipComposite{")
    for i in range(0, len(compose), 4):
        out.append("\t" + " ".join("{0x%x, 0x%x, 0x%x}," % t for t in compose[i:i + 4]))
    out.append("}")
    out.append("")
    ranges = []
    for cp in range(0x110000):
        c = unicodedata.combining(chr(cp))
        if not c:
            continue
        if ranges and ranges[-1][1] == cp - 1 and ranges[-1][2] == c:
            ranges[-1][1] = cp
        else:
            ranges.append([cp, cp, c])
    out.append("// zipCCC lists the runes with a non-zero canonical combining class, as inclusive ranges.")
    out.append("var zipCCC = []zipCCCRange{")
    for i in range(0, len(ranges), 4):
        out.append("\t" + " ".join("{0x%x, 0x%x, %d}," % tuple(t) for t in ranges[i:i + 4]))
    out.append("}")
    sys.stdout.write("\n".join(out) + "\n")


main()
